def tr_lower(s):
    """Türkçe kurallarına göre küçük harfe çevir."""
    result = []
    for ch in s:
        if ch == 'I':
            result.append('ı')
        elif ch == 'İ':
            result.append('i')
        else:
            result.append(ch.lower())
    return ''.join(result)


def tr_upper(s):
    """Türkçe kurallarına göre büyük harfe çevir."""
    result = []
    for ch in s:
        if ch == 'i':
            result.append('İ')
        elif ch == 'ı':
            result.append('I')
        else:
            result.append(ch.upper())
    return ''.join(result)


def tr_sorted(words):
    """Kelimeleri Türk alfabesine göre sıralanmış yeni liste döndür."""
    turk_order = "0123456789abcçdefgğhıijklmnoöpqrsştuüvwxyz"

    def sort_key(word):
        # Kelimeyi küçük harfe çevir (Türkçe kurallarıyla)
        lower_word = tr_lower(word)

        # Her karakter için sıralama anahtarı oluştur
        key_parts = []
        for ch in lower_word:
            if ch in turk_order:
                # Türk alfabesindeki pozisyon
                key_parts.append(turk_order.index(ch))
            else:
                # Türk alfabesinde olmayan karakterler (boşluk, noktalama vb.)
                # Unicode kod noktasına göre sıralanır ama tüm Türk harflerinden önce gelir
                key_parts.append(-ord(ch))

        return tuple(key_parts)

    # Kelimelerin orijinal dizilerini sakla (eşitlik durumunda girdideki sırayı korumak için)
    indexed_words = list(enumerate(words))

    # Sıralama anahtarına göre ve orijinal dizine göre ikili sıralama yap
    sorted_indexed = sorted(indexed_words, key=lambda x: (sort_key(x[1]), x[0]))

    # Sadece kelimeleri al
    return [word for _, word in sorted_indexed]

